mapper.select:
select id, kb_id, doc_name, file_path, content_text, status, chunk_count,
       create_by, create_time, update_by, update_time, remark
from ai_knowledge_doc where id = #{id}

mapper.update:
update ai_knowledge_doc
doc_name = #{docName}, file_path = #{filePath}, content_text = #{contentText}, status = #{status}, chunk_count = #{chunkCount}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark},
where id = #{id}
